(()=>{'use strict';const KEY='toolbox-appearance';const options=['system','light','dark'];const read=()=>{try{const v=localStorage.getItem(KEY);return options.includes(v)?v:'system'}catch{return 'system'}};
function set(v){if(!options.includes(v))return;try{localStorage.setItem(KEY,v)}catch{}document.documentElement.dataset.toolboxTheme=v;document.querySelectorAll('[data-appearance-choice]').forEach(b=>{const on=b.dataset.appearanceChoice===v;b.setAttribute('aria-pressed',String(on));b.classList.toggle('selected',on)})}
function render(){const view=document.getElementById('view');if(!view)return;const page=view.querySelector('.account-page');if(!page)return;const old=view.querySelector('#toolboxAppearance');if(old)old.remove();const section=document.createElement('section');section.id='toolboxAppearance';section.className='tb-appearance-row';section.setAttribute('aria-label','Appearance');section.innerHTML='<div class="tb-appearance-label"><span class="tb-appearance-title">Appearance</span><small>Display preference</small></div><div class="tb-appearance-segment" role="group" aria-label="Display preference">'+[['system','Auto'],['light','Light'],['dark','Dark']].map(([v,t])=>'<button type="button" data-appearance-choice="'+v+'" aria-pressed="'+(read()===v)+'" class="'+(read()===v?'selected':'')+'">'+t+'</button>').join('')+'</div>';page.appendChild(section);section.addEventListener('click',e=>{const b=e.target.closest('[data-appearance-choice]');if(b)set(b.dataset.appearanceChoice)});
page.querySelectorAll('.account-brand,.tb-account-credit').forEach(el=>el.remove());const foot=document.createElement('footer');foot.className='tb-account-credit';foot.innerHTML='<img src="assets/bulletproof-seafarer-official.png" alt="Bulletproof Seafarer logo" loading="lazy"><div><strong>Bulletproof Seafarer</strong><small>Developed by JV Ursal</small></div>';page.appendChild(foot)}
let queued=false;function init(){const view=document.getElementById('view');if(!view)return;new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;if(view.querySelector('.account-page')&&!view.querySelector('#toolboxAppearance'))render()})}).observe(view,{childList:true,subtree:false});render();set(read())}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init()})();